/* Mappings the first (Formerly-only) extraction missed — the catalog also uses "Replaces X"
   notes and merged-series notes. Verified against catalog.calpoly.edu/courses/. */
Object.assign(COURSE_EQUIV_SEED, {
  'BUS 342':'BUS 1342',   // BUS 1342 Financial Institutions "Replaces BUS 342"
  'MATH 141':'MATH 1261', // quarter Calc I/II/III (141/142/143) merged into semester 1261/1262/1263
  'MATH 142':'MATH 1262',
  'MATH 143':'MATH 1263'
});
/* current code -> { req:[ [orGroup],... ], concurrent:[codes] }. req = AND of OR-groups.
   INTENTIONALLY EMPTY — real data only, loaded from Supabase course_prereqs (catalog-scraped).
   Empty/missing ⇒ "not listed" (never blocks, never invents). */
const COURSE_PREREQS_SEED = {};
let COURSE_EQUIV={}, COURSE_EQUIV_REV={}, COURSE_PREREQS={};
function normCourse(code){ return String(code==null?'':code).toUpperCase().replace(/\s+/g,' ').trim(); }
function buildEquivIndex(){
  COURSE_EQUIV={}; COURSE_EQUIV_REV={};
  Object.keys(COURSE_EQUIV_SEED).forEach(function(k){ var legacy=normCourse(k), cur=normCourse(COURSE_EQUIV_SEED[k]); if(!legacy||!cur)return; COURSE_EQUIV[legacy]=cur; (COURSE_EQUIV_REV[cur]=COURSE_EQUIV_REV[cur]||[]).push(legacy); });
  // The class-search list is cached; drop it so quarter aliases get folded in on next build.
  try{ if(typeof taCache!=='undefined'&&taCache)taCache.classes=null; }catch(e){}
}
function buildPrereqIndex(){ COURSE_PREREQS={}; Object.keys(COURSE_PREREQS_SEED).forEach(function(k){ COURSE_PREREQS[normCourse(k)]=COURSE_PREREQS_SEED[k]; }); }
/* Canonical (current-semester) form of any code. Unmapped codes returned as-is (still valid/searchable). */
function canonCode(code){ var c=normCourse(code); return COURSE_EQUIV[c]||c; }
/* All known aliases (current + any legacy quarter numbers). */
function codeAliases(code){ var cur=canonCode(code), out=[cur]; (COURSE_EQUIV_REV[cur]||[]).forEach(function(l){if(out.indexOf(l)<0)out.push(l);}); return out; }
/* Same underlying course, regardless of quarter/semester numbering. */
function sameCourse(a,b){ return canonCode(a)===canonCode(b); }
/* Legacy quarter number for a current course (for the "previously offered as" hint). */
/* COURSE_EQUIV_REV can hold several legacy aliases for one canonical course (37 codes have
   two or more). Returning l[0] meant a student who typed CSC 101 could be told "was CPE 101"
   — the app contradicting what they had just entered with an alias for a different listing.
   Prefer the alias the student actually used when we know it; otherwise return nothing rather
   than pick one at random out of several equally-true answers. */
function legacyNumberOf(code,preferred){
  var l=COURSE_EQUIV_REV[canonCode(code)];
  if(!l||!l.length)return null;
  if(preferred){
    var pref=(typeof normCourse==='function')?normCourse(preferred):preferred;
    if(l.indexOf(pref)>=0)return pref;
  }
  return l.length===1?l[0]:null;
}
/* Describe the code the student ISN'T looking at. Typing a dead quarter number used to produce
   "Previously offered as BUS 200" while the field itself read BUS 200 — self-referential noise. */
function equivNote(code){
  var c=normCourse(code), cur=canonCode(c);
  if(cur&&cur!==c)return c+' is now '+cur+' on semesters — your review files under '+cur+'.';
  var l=legacyNumberOf(c);
  return l?('Previously offered as '+l+' under the quarter system'):'';
}
/* Prereq record (by canonical code). */
function coursePrereqs(code){ return COURSE_PREREQS[canonCode(code)]||null; }
function enrolledNowCodes(){
  var out=[];
  try{
    (typeof myClasses!=='undefined'?myClasses:[]).forEach(function(code){
      var m=(typeof myClassMeta!=='undefined')?myClassMeta[code]:null;
      var secs=secsOf(m);
      /* No section data means the student added the course by hand; treat that as enrolled,
         which is what "My Classes" means. With sections, at least one must be enrolled. */
      if(!secs||secs.some(function(x){return x.status!=='waitlisted';}))out.push(canonCode(code));
    });
  }catch(e){}
  return out;
}
function prereqStatus(code, completed, plannedBefore, inProgress){
  var p=coursePrereqs(code);
  if(!p||!p.req||!p.req.length) return {state:'none',missing:[],concurrent:[],inProgress:[]};
  var conc=new Set(((p.concurrent)||[]).map(canonCode));
  var have=new Set((completed||[]).map(canonCode));
  var before=new Set((plannedBefore||[]).map(canonCode));
  /* Default to what the student is actually enrolled in this term. Every caller used to pass
     only Past Classes, so a student taking BUS 3431 right now was told BUS 3443's prerequisite
     "isn't in your logged Past Classes" — true, and useless: they're sitting in it. */
  var now=new Set((inProgress||(typeof enrolledNowCodes==='function'?enrolledNowCodes():[])).map(canonCode));
  var missing=[], concOnly=[], nowOnly=[];
  p.req.forEach(function(group){
    var g=group.map(canonCode);
    if(g.some(function(x){return have.has(x)||before.has(x);})) return;              // satisfied
    if(g.some(function(x){return now.has(x);})){ nowOnly.push(group); return; }      // taking it this term
    if(g.some(function(x){return conc.has(x);})){ concOnly.push(group); return; }    // may be taken concurrently
    missing.push(group);
  });
  if(missing.length) return {state:'unmet',missing:missing,concurrent:concOnly,inProgress:nowOnly};
  if(nowOnly.length) return {state:'inprogress',missing:[],concurrent:concOnly,inProgress:nowOnly};
  if(concOnly.length) return {state:'concurrent',missing:[],concurrent:concOnly,inProgress:[]};
  return {state:'met',missing:[],concurrent:[],inProgress:[]};
}
function completedCodes(){
  var out=[],seen={};
  var add=function(c){ if(!c)return; try{ c=canonCode(c); }catch(e){} if(!seen[c]){seen[c]=1;out.push(c);} };
  try{ (typeof myHistory!=='undefined'?myHistory:[]).forEach(function(h){ if(h&&h.code)add(h.code); }); }catch(e){}
  try{ completedLocal().forEach(add); }catch(e){}
  try{ waivedCodes().forEach(add); }catch(e){}
  return out;
}
