    var pools={done:(haveList||[]).map(canon).filter(function(c){return !spent[c];}),
               taking:(takingList||[]).map(canon).filter(function(c){return !spent[c];})};
    /* dedupe within each pool, and never let one course sit in both */
    ['done','taking'].forEach(function(k){ var seen={}; pools[k]=pools[k].filter(function(c){ if(seen[c]||spent[c])return false; seen[c]=1; return true; }); });
    pools.taking=pools.taking.filter(function(c){ return pools.done.indexOf(c)<0; });
